"use client"

import * as React from "react"

// An editorial list of services set large in a serif. Point at a row and the
// rest of the list steps back and softens, the row slides forward, its number
// turns into an arrow, and a slow shader aura glides in behind it, lit in the
// palette and swirling under the pointer.

export type AuraItem = {
  title: string
  /** Small right-hand note, e.g. a count or a year. */
  meta?: string
  href?: string
  onClick?: () => void
}

export type AuraPalette = { ground: string; text: string; a: string; b: string; c: string }

export const AURA_PALETTES = {
  ember: { ground: "#0d0b0a", text: "#f4ede4", a: "#d9663e", b: "#f0b47a", c: "#9c3a5a" },
  tide: { ground: "#080c10", text: "#e9f0f4", a: "#2f7d8c", b: "#9fd4cf", c: "#3a4f9c" },
  moss: { ground: "#0b0d09", text: "#eef0e6", a: "#6d8a3a", b: "#d8c27a", c: "#2f6b55" },
} satisfies Record<string, AuraPalette>

export type AuraFocusListProps = {
  items?: AuraItem[]
  label?: string
  palette?: keyof typeof AURA_PALETTES | AuraPalette
  /** Stage height. Keep it a definite length; percentages collapse once installed. */
  height?: string
  className?: string
  onActive?: (index: number) => void
}

// #region helpers
export function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim()
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2]
  const n = parseInt(h.slice(0, 6), 16)
  if (Number.isNaN(n) || h.length < 6) return [0, 0, 0]
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255]
}

export function backing(css: number, dpr: number): number {
  return Math.max(1, Math.round(css * Math.min(2, Math.max(1, dpr || 1))))
}

export function pad2(n: number): string {
  return n < 10 ? "0" + n : String(n)
}

/** Frame-rate independent ease toward a target: k is the fraction closed per 60 fps frame. */
export function approach(from: number, to: number, k: number, dt: number): number {
  return to + (from - to) * Math.pow(1 - k, dt * 60)
}
// #endregion

const VERT = "attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}"

const FRAG =
  "precision highp float;" +
  "uniform vec2 uRes;uniform float uTime;uniform vec2 uC;uniform float uAmp;uniform float uRowH;" +
  "uniform vec3 uA;uniform vec3 uB;uniform vec3 uK;uniform vec3 uG;" +
  "float hash(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}" +
  "void main(){vec2 f=gl_FragCoord.xy;vec2 d=(f-uC)/uRes.y;" +
  // a wide soft ellipse behind the row, its edge stirred by slow sine warps
  "vec2 q=d*vec2(1.15,uRes.y/(uRowH*1.7));float t=uTime;" +
  "vec2 w=d*3.;for(int i=1;i<5;i++){float fi=float(i);w+=vec2(.5/fi*sin(fi*w.y+t*.7+fi),.4/fi*cos(fi*w.x-t*.6+fi*1.7));}" +
  "float body=exp(-dot(q,q)*1.9)*(.7+.3*sin(w.x*1.5+w.y));" +
  "float sw=.5+.5*sin(w.x*1.2-w.y*.9+t*.4);" +
  "vec3 col=mix(uA,uK,sw);col=mix(col,uB,smoothstep(.55,1.,body)*.7);" +
  "float a=clamp(body*uAmp,0.,1.);" +
  "vec3 o=mix(uG,col,a)+col*a*a*.22+(hash(f+fract(t)*77.)-.5)*.025*a;" +
  "gl_FragColor=vec4(o,1.);}"

const FONT =
  "@font-face{font-family:'AFL Serif';src:url(data:font/woff2;base64,) format('woff2');font-style:normal;font-weight:400;font-display:swap}" +
  "@font-face{font-family:'AFL Serif';src:url(data:font/woff2;base64,) format('woff2');font-style:italic;font-weight:400;font-display:swap}"

const EASE = "cubic-bezier(.22,1.2,.36,1)"

const CSS =
  FONT +
  ".afl-root{position:relative;width:100%;overflow:hidden;isolation:isolate;display:flex;align-items:center;background:var(--afl-ground);color:var(--afl-text);font-family:ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif}" +
  ".afl-root *{box-sizing:border-box}" +
  ".afl-host{position:absolute;inset:0;pointer-events:none}" +
  ".afl-root::after{content:'';position:absolute;inset:0;z-index:0;pointer-events:none;background:radial-gradient(120% 80% at 50% 50%,transparent 50%,rgba(0,0,0,.45))}" +
  ".afl-canvas{position:absolute;inset:0;width:100%;height:100%;display:block}" +
  ".afl-wrap{position:relative;z-index:1;width:100%;max-width:1180px;margin:0 auto;padding:0 clamp(20px,5vw,64px)}" +
  ".afl-head{display:flex;justify-content:space-between;align-items:baseline;padding-bottom:18px;font-size:12px;letter-spacing:.16em;text-transform:uppercase;opacity:.55;border-bottom:1px solid color-mix(in oklab,var(--afl-text) 16%,transparent)}" +
  ".afl-list{list-style:none;margin:0;padding:0}" +
  ".afl-item{border-bottom:1px solid color-mix(in oklab,var(--afl-text) 10%,transparent)}" +
  ".afl-row{position:relative;display:grid;grid-template-columns:56px 1fr auto;align-items:center;gap:16px;width:100%;padding:clamp(10px,1.6vw,18px) 0;border:0;background:none;color:inherit;text-align:left;text-decoration:none;cursor:pointer;font:inherit;outline:none;" +
  "opacity:0;transform:translateY(24px);transition:opacity .9s ease,transform 1.1s cubic-bezier(.16,1,.3,1),filter .5s ease}" +
  ".afl-in .afl-row{opacity:1;transform:none}" +
  ".afl-list[data-active] .afl-row{opacity:.24;filter:blur(1.2px);transform:translateX(-10px);transition:opacity .45s ease,transform .7s " + EASE + ",filter .45s ease}" +
  ".afl-list[data-active] .afl-row.afl-on{opacity:1;filter:none;transform:translateX(22px)}" +
  ".afl-row:focus-visible .afl-title{text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:.14em}" +
  ".afl-icon{position:relative;width:40px;height:40px}" +
  ".afl-num,.afl-arrow{position:absolute;inset:0;display:grid;place-items:center;transition:opacity .35s ease,transform .6s " + EASE + "}" +
  ".afl-num{font-size:13px;letter-spacing:.06em;font-variant-numeric:tabular-nums;opacity:.6}" +
  ".afl-arrow{opacity:0;transform:rotate(-90deg) scale(.4);border-radius:50%;background:var(--afl-text);color:var(--afl-ground)}" +
  ".afl-on .afl-num{opacity:0;transform:translateY(-8px)}" +
  ".afl-on .afl-arrow{opacity:1;transform:none}" +
  ".afl-title{font-family:'AFL Serif',ui-serif,Georgia,serif;font-weight:400;font-size:clamp(38px,7vw,112px);line-height:1;letter-spacing:-.025em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;transition:letter-spacing .7s " + EASE + "}" +
  ".afl-on .afl-title{font-style:italic;letter-spacing:-.035em}" +
  ".afl-meta{font-size:13px;opacity:0;transform:translateX(-12px);transition:opacity .4s ease,transform .6s " + EASE + "}" +
  ".afl-on .afl-meta{opacity:.7;transform:none}" +
  "@media (max-width:640px){.afl-title{font-size:clamp(34px,10.5vw,60px)}.afl-row{grid-template-columns:36px 1fr;gap:10px}.afl-meta{display:none}.afl-icon{width:30px;height:30px}.afl-list[data-active] .afl-row.afl-on{transform:translateX(10px)}}" +
  "@media (prefers-reduced-motion:reduce){.afl-row,.afl-list[data-active] .afl-row,.afl-num,.afl-arrow,.afl-meta,.afl-title{transition:opacity .2s ease}.afl-list[data-active] .afl-row,.afl-list[data-active] .afl-row.afl-on{transform:none;filter:none}}"

function compile(gl: WebGLRenderingContext, type: number, src: string) {
  const s = gl.createShader(type)
  if (!s) return null
  gl.shaderSource(s, src)
  gl.compileShader(s)
  if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
    console.warn("aura-focus-list:", gl.getShaderInfoLog(s))
    gl.deleteShader(s)
    return null
  }
  return s
}

const DEFAULT_ITEMS: AuraItem[] = [
  { title: "Brand identity", meta: "38 projects" },
  { title: "Art direction", meta: "24 projects" },
  { title: "Interaction design", meta: "41 projects" },
  { title: "Creative coding", meta: "17 projects" },
  { title: "Motion & film", meta: "29 projects" },
]

export default function AuraFocusList({
  items = DEFAULT_ITEMS,
  label = "What we do",
  palette = "ember",
  height = "100svh",
  className,
  onActive,
}: AuraFocusListProps) {
  const root = React.useRef(null as HTMLElement | null)
  const host = React.useRef(null as HTMLDivElement | null)
  const list = React.useRef(null as HTMLUListElement | null)
  const [ready, setReady] = React.useState(false)
  const [active, setActive] = React.useState(-1)
  const [settled, setSettled] = React.useState(false)
  const pal = typeof palette === "string" ? AURA_PALETTES[palette] || AURA_PALETTES.ember : palette
  // The GL loop reads these; React writes them.
  const live = React.useRef({ pal, active: -1, px: 0.5, kick: () => {} })
  live.current.pal = pal
  live.current.active = active

  React.useEffect(() => {
    if (ready && !settled) {
      const id = window.setTimeout(() => setSettled(true), 1500)
      return () => window.clearTimeout(id)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ready])

  React.useEffect(() => {
    onActive?.(active)
    live.current.kick()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active])

  React.useEffect(() => {
    const el = root.current
    const holder = host.current
    const ul = list.current
    if (!el || !holder || !ul) return
    const raf0 = requestAnimationFrame(() => setReady(true))
    // A fresh canvas per mount: a context lost on unmount can't be reused (StrictMode remounts).
    const cv = document.createElement("canvas")
    cv.className = "afl-canvas"
    holder.appendChild(cv)
    const gl = cv.getContext("webgl", { antialias: false, alpha: false })
    const vs = gl && compile(gl, gl.VERTEX_SHADER, VERT)
    const fs = gl && compile(gl, gl.FRAGMENT_SHADER, FRAG)
    const prog = gl && gl.createProgram()
    if (!gl || !vs || !fs || !prog) {
      cv.remove()
      return () => cancelAnimationFrame(raf0)
    }
    gl.attachShader(prog, vs)
    gl.attachShader(prog, fs)
    gl.linkProgram(prog)
    gl.useProgram(prog)
    const buf = gl.createBuffer()
    gl.bindBuffer(gl.ARRAY_BUFFER, buf)
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW)
    const loc = gl.getAttribLocation(prog, "p")
    gl.enableVertexAttribArray(loc)
    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0)
    const u = (n: string) => gl.getUniformLocation(prog, n)
    const U = { res: u("uRes"), time: u("uTime"), c: u("uC"), amp: u("uAmp"), rowH: u("uRowH"), a: u("uA"), b: u("uB"), k: u("uK"), g: u("uG") }

    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)")
    // Row centres and sizes, measured on init and resize only.
    const geo = { w: 1, h: 1, dpr: 1, left: 0, rows: [] as { y: number; h: number }[] }
    const s = { y: 0, x: 0.5, amp: 0, t: 0 }
    let raf = 0
    let running = false
    let onScreen = true
    let last = performance.now()

    const measure = () => {
      const r = el.getBoundingClientRect()
      geo.w = r.width
      geo.h = r.height
      geo.left = r.left
      geo.dpr = Math.min(2, Math.max(1, window.devicePixelRatio || 1))
      // Offsets ignore the rows' transforms. Rows sit in .afl-wrap, which sits in the section.
      const wrapTop = (ul.parentElement as HTMLElement).offsetTop
      geo.rows = Array.from(ul.children).map((li) => {
        const n = li as HTMLElement
        return { y: wrapTop + n.offsetTop + n.offsetHeight / 2, h: n.offsetHeight }
      })
      cv.width = backing(r.width, geo.dpr)
      cv.height = backing(r.height, geo.dpr)
      gl.viewport(0, 0, cv.width, cv.height)
      draw(0)
    }
    const draw = (dt: number) => {
      const L = live.current
      const row = geo.rows[L.active]
      const target = row ? 1 : 0
      if (row) s.y = s.amp < 0.02 ? row.y : approach(s.y, row.y, 0.14, dt)
      s.x = approach(s.x, L.px, 0.06, dt)
      s.amp = reduce.matches ? target : approach(s.amp, target, 0.08, dt)
      if (!reduce.matches) s.t += dt
      const rh = (row ? row.h : geo.rows[0]?.h || 80) * geo.dpr
      const c = [L.pal.a, L.pal.b, L.pal.c, L.pal.ground].map(hexToRgb)
      gl.uniform2f(U.res, cv.width, cv.height)
      gl.uniform1f(U.time, s.t)
      gl.uniform2f(U.c, s.x * cv.width, cv.height - s.y * geo.dpr)
      gl.uniform1f(U.amp, s.amp)
      gl.uniform1f(U.rowH, rh)
      gl.uniform3f(U.a, c[0][0], c[0][1], c[0][2])
      gl.uniform3f(U.b, c[1][0], c[1][1], c[1][2])
      gl.uniform3f(U.k, c[2][0], c[2][1], c[2][2])
      gl.uniform3f(U.g, c[3][0], c[3][1], c[3][2])
      gl.drawArrays(gl.TRIANGLES, 0, 3)
    }
    const loop = (now: number) => {
      const dt = Math.min(0.05, (now - last) / 1000)
      last = now
      draw(dt)
      // Idle once the aura has faded out: no frames spent on an empty ground.
      const idle = live.current.active < 0 && s.amp < 0.002
      running = onScreen && !document.hidden && !idle
      raf = running ? requestAnimationFrame(loop) : 0
    }
    const kick = () => {
      if (running || !onScreen || document.hidden) return
      running = true
      last = performance.now()
      raf = requestAnimationFrame(loop)
    }
    live.current.kick = kick
    const onEnter = () => (geo.left = el.getBoundingClientRect().left)
    const onMove = (e: PointerEvent) => {
      live.current.px = geo.w > 0 ? Math.min(0.8, Math.max(0.25, (e.clientX - geo.left) / geo.w)) : 0.5
    }

    const ro = new ResizeObserver(measure)
    ro.observe(el)
    const io = new IntersectionObserver(([e]) => {
      onScreen = e.isIntersecting
      if (onScreen) kick()
    })
    io.observe(el)
    const onVis = () => !document.hidden && kick()
    document.addEventListener("visibilitychange", onVis)
    el.addEventListener("pointerenter", onEnter)
    el.addEventListener("pointermove", onMove)
    // Fonts change row heights after first paint.
    document.fonts?.ready.then(() => measure())
    measure()

    return () => {
      cancelAnimationFrame(raf0)
      cancelAnimationFrame(raf)
      running = false
      live.current.kick = () => {}
      ro.disconnect()
      io.disconnect()
      document.removeEventListener("visibilitychange", onVis)
      el.removeEventListener("pointerenter", onEnter)
      el.removeEventListener("pointermove", onMove)
      gl.deleteBuffer(buf)
      gl.deleteProgram(prog)
      gl.deleteShader(vs)
      gl.deleteShader(fs)
      gl.getExtension("WEBGL_lose_context")?.loseContext()
      cv.remove()
    }
  }, [])

  return (
    <section
      ref={root}
      className={"afl-root" + (ready ? " afl-in" : "") + (className ? " " + className : "")}
      style={{ height, "--afl-ground": pal.ground, "--afl-text": pal.text } as React.CSSProperties}
      onPointerLeave={() => setActive(-1)}
    >
      <style>{CSS}</style>
      <div ref={host} className="afl-host" aria-hidden="true" />
      <div className="afl-wrap">
        {label ? (
          <div className="afl-head">
            <span>{label}</span>
            <span>{pad2(items.length)}</span>
          </div>
        ) : null}
        <ul ref={list} className="afl-list" data-active={active >= 0 ? "" : undefined} onBlur={(e) => !e.currentTarget.contains(e.relatedTarget as Node) && setActive(-1)}>
          {items.map((it, i) => {
            const props = {
              className: "afl-row" + (i === active ? " afl-on" : ""),
              // The entrance staggers; after it, hovers respond at once.
              style: settled ? undefined : { transitionDelay: 0.2 + i * 0.08 + "s" },
              onPointerEnter: () => setActive(i),
              onFocus: () => setActive(i),
              onClick: it.onClick,
            }
            const inner = (
              <>
                <span className="afl-icon" aria-hidden="true">
                  <span className="afl-num">{pad2(i + 1)}</span>
                  <span className="afl-arrow">
                    <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                      <path d="M4 12L12 4M6 4h6v6" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" />
                    </svg>
                  </span>
                </span>
                <span className="afl-title">{it.title}</span>
                {it.meta ? <span className="afl-meta">{it.meta}</span> : <span />}
              </>
            )
            return (
              <li className="afl-item" key={i}>
                {it.href ? (
                  <a href={it.href} {...props}>
                    {inner}
                  </a>
                ) : (
                  <button type="button" {...props}>
                    {inner}
                  </button>
                )}
              </li>
            )
          })}
        </ul>
      </div>
    </section>
  )
}
